function activateTab(t){const e=document.querySelectorAll(".kbm-tab"),n=document.querySelectorAll(".kbm-section");if(!e.length||!n.length)return;e.forEach(t=>t.classList.remove("active")),n.forEach(t=>t.classList.remove("active"));const o=document.querySelector(`.kbm-tab[data-tab="${t}"]`),i=document.getElementById(t);o&&o.classList.add("active"),i&&(i.classList.add("active"),i.scrollIntoView({behavior:"smooth",block:"start"}))}function initTabNavigation(){document.querySelectorAll(".kbm-tab").forEach(t=>{t.addEventListener("click",()=>activateTab(t.dataset.tab))});const t=window.location.hash.replace("#","");if(t){["biography","timeline","resistance","significance","gallery","references"].includes(t)&&activateTab(t)}}function initThemeToggle(){const t=document.getElementById("theme-toggle");if(!t)return;updateThemeIcon(localStorage.getItem("theme")||"dark"),t.addEventListener("click",()=>{const t=document.body;t.classList.contains("light-theme")?(t.classList.remove("light-theme"),localStorage.setItem("theme","dark"),updateThemeIcon("dark")):(t.classList.add("light-theme"),localStorage.setItem("theme","light"),updateThemeIcon("light"))})}function updateThemeIcon(t){const e=document.getElementById("theme-toggle");e&&(e.textContent="light"===t?"🌙":"☀️")}function initSmoothScroll(){document.querySelectorAll('a[href^="#"]').forEach(t=>{t.addEventListener("click",function(t){const e=document.querySelector(this.getAttribute("href"));e&&(t.preventDefault(),e.scrollIntoView({behavior:"smooth",block:"start"}))})})}function initMobileMenu(){const t=document.getElementById("menu-toggle"),e=document.getElementById("nav-menu");t&&e&&t.addEventListener("click",()=>{const n="true"===t.getAttribute("aria-expanded");t.setAttribute("aria-expanded",String(!n)),e.classList.toggle("active")})}function initCountUp(){const t=document.querySelectorAll(".kbm-count");if(!t.length)return;const e=new IntersectionObserver((t,e)=>{t.forEach(t=>{if(t.isIntersecting){const n=t.target,o=parseInt(n.getAttribute("data-target"),10);if(isNaN(o))return;let i=0;const a=Math.max(1,Math.floor(o/60)),c=()=>{i+=a,i>o&&(i=o),n.textContent=i,i<o&&requestAnimationFrame(c)};c(),e.unobserve(n)}})},{threshold:.6});t.forEach(t=>e.observe(t))}document.addEventListener("DOMContentLoaded",()=>{initTabNavigation(),initThemeToggle(),initSmoothScroll(),initMobileMenu(),initCountUp()});